command:
$ErrorActionPreference = "Stop"
git fetch origin main --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch main failed" }
if ((git rev-parse origin/main).Trim() -ne "84a559c4c8fbac7409ddd46f5ecdde0b7e3bc0ce") { throw "main moved" }

git -C $env:GITHUB_WORKSPACE push origin --delete work/large-folder-paging
if ($LASTEXITCODE -ne 0) { throw "large-folder paging branch cleanup failed" }

Write-Host "LARGE_FOLDER_PAGING_WORK_BRANCH_DELETED"
